#!/usr/bin/env bash
# AKFC — Partenaires du club (MJC, FFK…), incrément 1 : back-end (sans écran).
#  Schéma + migration 20261125000000_site_partners : SitePartner (nom, rôle HOST/FEDERATION/OTHER,
#    description, site, liens utiles [{label,url}], logo en base, ordre, actif) — doc /// complète.
#  Router « sitePartner » : list (public, actifs) ; listAdmin, save, setLogo, clearLogo, delete,
#    reorder (admins). Liens http(s) seulement. Logo SVG/PNG/WebP/JPEG ≤ 512 Ko, signature
#    vérifiée ; SVG à contenu actif (script, on…=, javascript:, ressource externe) refusé.
#  Route publique /api/site-partners/[id]/logo (cache long versionné, sandbox + nosniff).
#  Démarrage : crée « MJC de Chambéry » (accueil) et « FFK » (fédération) s'il n'y a AUCUN
#    partenaire — les logos s'ajoutent ensuite dans Réglages du site (incrément suivant).
#  Preuves avant commit (sinon TOUT est restauré) : prisma validate, generate, pnpm check,
#  puis sur la base LOCALE : migrate deploy + migrate diff VIDE.
# Usage : bash apply-site-partners-backend.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
S="prisma/schema.prisma"
grep -q "^model Ticket " "$S" || { echo "ERREUR: applique d'abord les incréments tickets." >&2; exit 1; }
grep -q "^model SitePartner " "$S" && { echo "— déjà appliqué"; exit 0; }
MIG="prisma/migrations/20261125000000_site_partners"
MOD="packages/backend/src/modules/sitePartners"
ROUTE="apps/web/src/app/api/site-partners/[id]/logo/route.ts"
FILES=("$S" packages/backend/src/modules/index.ts apps/web/src/instrumentation.ts)
for p in "$MIG" "$MOD" "$ROUTE"; do [ -e "$p" ] && { echo "ERREUR: $p existe déjà." >&2; exit 1; }; done
BK=/tmp/akfc_sp_backup; rm -rf "$BK"; mkdir -p "$BK"
for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; done
restore(){ for f in "${FILES[@]}"; do cp "$BK/$f" "$f"; done; rm -rf "$MIG" "$MOD" "apps/web/src/app/api/site-partners"; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }

W=/tmp/akfc_sp; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/schema_edit.py"
echo '' | base64 -d > "$W/block.prisma"
echo '' | base64 -d > "$W/edit.py"
echo '' | base64 -d > /tmp/akfc_sp_rollback.sql

echo "== application =="
python3 "$W/schema_edit.py" "$S" "$W/block.prisma" || { restore; exit 1; }
mkdir -p "$MIG" && echo '' | base64 -d > "$MIG/migration.sql" && echo "  ok  migration $MIG"
mkdir -p "$MOD" "$(dirname "$ROUTE")"
echo '' | base64 -d > "$MOD/sitePartners.service.ts"
echo '' | base64 -d > "$MOD/router.ts"
echo '' | base64 -d > "$ROUTE"
echo "  ok  module sitePartners + route du logo"
python3 "$W/edit.py" . || { restore; exit 1; }

if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi

PRISMA(){ pnpm exec prisma "$@" 2>/dev/null || pnpm --filter @workspace/backend exec prisma "$@"; }
echo "== prisma validate / generate =="
PRISMA validate --schema "$S" > /tmp/akfc_v.log 2>&1 || { tail -8 /tmp/akfc_v.log; restore; exit 1; }
PRISMA generate > /tmp/akfc_g.log 2>&1 || { tail -8 /tmp/akfc_g.log; restore; exit 1; }
echo "  ✅ schéma valide, client généré"
echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"

echo "== base LOCALE : migrate deploy + migrate diff (doit être VIDE) =="
DBURL=$(grep -E '^DATABASE_URL=' .env 2>/dev/null | head -1 | cut -d= -f2- | tr -d '"' || true)
HOST=$(python3 -c "import sys;from urllib.parse import urlparse;print(urlparse(sys.argv[1]).hostname or '')" "$DBURL" 2>/dev/null || true)
case "$HOST" in
  localhost|127.0.0.1|::1) echo "  base : $HOST (locale)";;
  *) echo "❌ DATABASE_URL (.env) ne pointe pas vers une base LOCALE (hôte « $HOST »). Par sécurité, rien n'est migré."; restore; exit 1;;
esac
if ! PRISMA migrate deploy > /tmp/akfc_md.log 2>&1; then
  echo "❌ migrate deploy a échoué :"; tail -12 /tmp/akfc_md.log
  echo "   Annuler sur la base LOCALE : psql \"<DATABASE_URL>\" -f /tmp/akfc_sp_rollback.sql"
  restore; exit 1
fi
set +e
PRISMA migrate diff --from-url "$DBURL" --to-schema-datamodel "$S" --exit-code > /tmp/akfc_d.log 2>&1
code=$?; set -e
case $code in
  0) echo "  ✅ base migrée = schéma (aucune dérive)";;
  *) echo "❌ la base migrée ne correspond pas au schéma (code $code) :"; head -20 /tmp/akfc_d.log
     echo "   Annuler sur la base LOCALE : psql \"<DATABASE_URL>\" -f /tmp/akfc_sp_rollback.sql"
     restore; exit 1;;
esac

git add "${FILES[@]}" "$MIG" "$MOD" "$ROUTE"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
feat(partners): partenaires du club (MJC, FFK) — modèle, router, route du logo

